	static boolean safeContextKeys(PatternPlan left, PatternPlan right, long keyMask) {
		long remaining = keyMask;
		while (remaining != 0L) {
			int slot = Long.numberOfTrailingZeros(remaining);
			if ((left.quadPositionOfSlot(slot) == TripleIndex.CONTEXT_IDX
					|| right.quadPositionOfSlot(slot) == TripleIndex.CONTEXT_IDX)
					&& !(left.namedContextScope && right.namedContextScope)) {
				return false;
			}
			remaining &= remaining - 1;
		}
		return true;
	}

